; tick.asm -- chapter 1: a sprite that moves one pixel every frame
; generated by gen01.py
        INCLUDE "msx.inc"
        OUTPUT "tick.rom"
        ORG $4000
        CART_HEADER init
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; 16 KB, display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000
        VDP_REG 4, $03          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, 1          ; border colour
        VRAM_WRITE 0            ; clear all 16 KB
        ld bc, $4000
.clear: xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clear
        VRAM_WRITE $1800        ; names: 0-255 in each third
        ld c, 3
.third: xor a
.name:  out (VDP_DATA), a
        inc a
        jr nz, .name
        dec c
        jr nz, .third
        VRAM_WRITE $2000        ; colours: 0x11 everywhere
        ld bc, 6144
.col:   ld a, $11
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .col
        VRAM_WRITE $1B00        ; no sprites yet
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; sprite pattern 0: the ball
        ld hl, ball
        ld b, 32
.pat:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .pat
        VRAM_WRITE $1B00        ; the attribute table: Y, X, pattern, colour
        ld hl, attrs
        ld b, 5
.att:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .att
        VDP_REG 1, $C2          ; display on, 16 x 16 sprites
        ld e, 0                 ; X
frame:  in a, (VDP_CTRL)        ; wait for the frame flag
        rlca
        jr nc, frame
        inc e                   ; one pixel to the right, every frame
        VRAM_WRITE $1B01        ; X of sprite 0
        ld a, e
        out (VDP_DATA), a
        jr frame
ball:
        db $01, $0F, $1F, $3F, $7F, $7F, $7F, $FF
        db $FF, $7F, $7F, $7F, $3F, $1F, $0F, $01
        db $80, $F0, $F8, $FC, $FE, $FE, $FE, $FF
        db $FF, $FE, $FE, $FE, $FC, $F8, $F0, $80
attrs:                          ; Y, X, pattern, colour ... and $D0
        db $58, $00, $00, $0F
        db $D0
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
